 /*
 * Recebe todas as linhas do node Leads.
 * Retorna um item SALVAR_LEAD para cada linha.
 */

const EMPRESA_ID = 1;

function normalizarChave(chave) {
  return String(chave || "")
    .replace(/^\uFEFF/, "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function limparLinha(linha) {
  const resultado = {};

  for (const [chave, valor] of Object.entries(linha || {})) {
    resultado[normalizarChave(chave)] = valor;
  }

  return resultado;
}

function texto(valor) {
  if (valor === null || valor === undefined) {
    return "";
  }

  return String(valor).trim();
}

const itens = $input.all();
const saida = [];

for (let indice = 0; indice < itens.length; indice += 1) {
  const linha = limparLinha(itens[indice].json);

  const lead = {
    tipo_lead: texto(linha.tipo_lead).toUpperCase() || "PJ",

    nome: texto(linha.nome),

    empresa_nome: texto(
      linha.empresa_nome ||
      linha.empresa ||
      linha.nome_empresa
    ),

    segmento: texto(
      linha.segmento ||
      linha.ramo ||
      linha.atividade
    ),

    cidade: texto(
      linha.cidade ||
      linha.municipio
    ),

    telefone: texto(
      linha.telefone ||
      linha.celular ||
      linha.whatsapp ||
      linha.fone
    ),

    instagram: texto(
      linha.instagram ||
      linha.insta
    ),

    email: texto(
      linha.email ||
      linha.e_mail
    ).toLowerCase(),

    canal_preferido: texto(
      linha.canal_preferido ||
      linha.canal
    ).toUpperCase(),

    origem: texto(
      linha.origem ||
      linha.fonte
    ),

    observacoes: texto(
      linha.observacoes ||
      linha.observacao ||
      linha.obs
    )
  };

  if (!["PF", "PJ"].includes(lead.tipo_lead)) {
    lead.tipo_lead = "PJ";
  }

  if (!lead.canal_preferido) {
    if (lead.telefone) {
      lead.canal_preferido = "WHATSAPP";
    } else if (lead.instagram) {
      lead.canal_preferido = "INSTAGRAM";
    } else if (lead.email) {
      lead.canal_preferido = "EMAIL";
    } else {
      lead.canal_preferido = "WHATSAPP";
    }
  }

  if (!lead.nome) {
    throw new Error(
      `Linha ${indice + 2}: nome do lead não informado.`
    );
  }

  if (!lead.telefone && !lead.instagram && !lead.email) {
    throw new Error(
      `Linha ${indice + 2}: informe telefone, Instagram ou e-mail.`
    );
  }

  saida.push({
    json: {
      empresa_id: EMPRESA_ID,
      acao: "SALVAR_LEAD",
      payload: lead
    }
  });
}

return saida;

  const entrada = $input.first().json;
const payload = entrada.body ?? entrada;

const eventoEvolution = String(payload.event ?? '')
  .trim()
  .toLowerCase();

const data = payload.data ?? {};
const key = data.key ?? {};

const tipoEvento = eventoEvolution.includes('call')
  ? 'LIGACAO'
  : 'MENSAGEM';

// --------------------------------------------------
// DIREÇÃO DA MENSAGEM
// --------------------------------------------------

const fromMeOriginal = key.fromMe ?? data.fromMe;

if (
  tipoEvento === 'MENSAGEM' &&
  typeof fromMeOriginal !== 'boolean'
) {
  throw new Error(
    `A Evolution não informou data.key.fromMe corretamente. Valor recebido: ${JSON.stringify(fromMeOriginal)}`
  );
}

const enviadaPorMim = tipoEvento === 'LIGACAO'
  ? fromMeOriginal === true
  : fromMeOriginal;

const direcao = enviadaPorMim
  ? 'ENVIADA_POR_MIM'
  : 'RECEBIDA_DO_CLIENTE';

// --------------------------------------------------
// IDENTIFICAÇÃO DO CONTATO
// --------------------------------------------------

const identificadores = [
  key.remoteJidAlt,
  data.remoteJidAlt,
  key.remoteJid,
  data.remoteJid,
  data.from,
  data.chatId
]
  .filter(valor => valor !== null && valor !== undefined)
  .map(valor => String(valor).trim())
  .filter(Boolean);

// Ignora grupos
if (identificadores.some(jid => jid.endsWith('@g.us'))) {
  return [];
}

const jidTelefone =
  identificadores.find(jid =>
    jid.endsWith('@s.whatsapp.net')
  ) ?? null;

const jidLid =
  identificadores.find(jid =>
    jid.endsWith('@lid')
  ) ?? null;

const numeroSemJid =
  identificadores.find(valor =>
    /^\+?\d{10,15}$/.test(valor)
  ) ?? null;

const telefoneCliente = jidTelefone
  ? jidTelefone
      .replace('@s.whatsapp.net', '')
      .replace(/\D/g, '')
  : numeroSemJid
    ? numeroSemJid.replace(/\D/g, '')
    : null;

const jidCliente =
  jidTelefone ??
  jidLid ??
  numeroSemJid ??
  null;

// --------------------------------------------------
// CONTEÚDO DA MENSAGEM
// --------------------------------------------------

const mensagem =
  data.message?.conversation ??
  data.message?.extendedTextMessage?.text ??
  data.message?.imageMessage?.caption ??
  data.message?.videoMessage?.caption ??
  data.message?.documentMessage?.caption ??
  data.message?.buttonsResponseMessage?.selectedDisplayText ??
  data.message?.listResponseMessage?.title ??
  null;

// --------------------------------------------------
// DATA DO EVENTO
// --------------------------------------------------

let dataEvento = payload.date_time ?? null;

if (!dataEvento && data.messageTimestamp) {
  const timestamp = Number(data.messageTimestamp);

  if (Number.isFinite(timestamp)) {
    dataEvento = new Date(timestamp * 1000).toISOString();
  }
}

dataEvento ??= new Date().toISOString();

// --------------------------------------------------
// VALIDAÇÕES
// --------------------------------------------------

if (!payload.instance) {
  throw new Error('A Evolution não informou o nome da instância.');
}

if (!jidCliente) {
  throw new Error(
    'Não foi possível identificar o contato no payload da Evolution.'
  );
}

// --------------------------------------------------
// RESULTADO
// --------------------------------------------------

return [
  {
    json: {
      tipo_evento: tipoEvento,
      direcao,
      from_me: enviadaPorMim,

      telefone_cliente: telefoneCliente,
      jid_cliente: jidCliente,
      identificador_lid: jidLid,

      nome_cliente: data.pushName ?? null,
      mensagem,
      mensagem_id: key.id ?? data.id ?? null,

      instancia: String(payload.instance),
      evento_evolution: eventoEvolution,
      data_evento: dataEvento
    }
  }
];

 const empresaId = 1;

// Funciona tanto se a Evolution entregar vários items
// quanto se entregar um array dentro de data/body.
const recebidos = $input.all().flatMap((item) => {
  const json = item.json;

  if (Array.isArray(json)) return json;
  if (Array.isArray(json.data)) return json.data;
  if (Array.isArray(json.body)) return json.body;

  return [json];
});

const contatosPorTelefone = new Map();

let ignoradosGrupo = 0;
let ignoradosLid = 0;
let ignoradosNewsletter = 0;
let ignoradosSemNome = 0;
let ignoradosInvalidos = 0;
let duplicadosNoRetorno = 0;

for (const contato of recebidos) {
  const jid = String(contato.remoteJid || "").trim();

  // Ignora grupos
  if (contato.isGroup === true || jid.endsWith("@g.us")) {
    ignoradosGrupo++;
    continue;
  }

  // Ignora identificadores LID
  if (jid.endsWith("@lid")) {
    ignoradosLid++;
    continue;
  }

  // Ignora canais
  if (jid.endsWith("@newsletter")) {
    ignoradosNewsletter++;
    continue;
  }

  // Aceita somente números normais do WhatsApp
  if (!jid.endsWith("@s.whatsapp.net")) {
    ignoradosInvalidos++;
    continue;
  }

  const telefone = jid.replace("@s.whatsapp.net", "").replace(/\D/g, "");
  const nome = String(contato.pushName || "").trim();

  // Validação do telefone
  if (
    telefone === "0" ||
    telefone.length < 10 ||
    telefone.length > 15
  ) {
    ignoradosInvalidos++;
    continue;
  }

  // Sua proc exige nome
  if (!nome) {
    ignoradosSemNome++;
    continue;
  }

  // Evita telefone repetido dentro do próprio retorno
  if (contatosPorTelefone.has(telefone)) {
    duplicadosNoRetorno++;
    continue;
  }

  contatosPorTelefone.set(telefone, {
    tipo_lead: "PF",
    nome,
    telefone,
    email: null,
    instagram: null,
    empresa_nome: null,
    segmento: null,
    cidade: null,
    canal_preferido: "WHATSAPP",
    origem: "WHATSAPP",
    observacoes: "Contato importado automaticamente do WhatsApp",
    tipo_importacao: "CONTATOS_WHATSAPP"
  });
}

const payload = Array.from(contatosPorTelefone.values());

return [
  {
    json: {
      empresa_id: empresaId,
      acao: "SALVAR_LEAD",
      payload,
      resumo: {
        recebidos: recebidos.length,
        prontos_para_enviar: payload.length,
        ignorados_grupo: ignoradosGrupo,
        ignorados_lid: ignoradosLid,
        ignorados_newsletter: ignoradosNewsletter,
        ignorados_sem_nome: ignoradosSemNome,
        ignorados_invalidos: ignoradosInvalidos,
        duplicados_no_retorno: duplicadosNoRetorno
      }
    }
  }
];

 const origem = $("EditaReverter2").item.json;

const erro = $json.error || null;
const mensagemErro = String(erro?.message || "");
const mensagemLimpa = mensagemErro.replace(/\\/g, "");

let resultado_envio;

if (!erro) {
  resultado_envio = "ENVIADO";
} else if (
  Number(erro.status) === 400 &&
  mensagemLimpa.includes('"exists":false')
) {
  resultado_envio = "ZAP_INVALIDO";
} else {
  resultado_envio = "ERRO_TECNICO";
}

return {
  json: {
    ...origem,
    resultado_envio,
    erro_envio: mensagemErro,
    resposta_evolution: $json,
  },
};

 let telefone = String(  $('EditaReverter2').first().json.telefone|| "").replace(/\D/g, "");

// Retira o zero antes do DDD
telefone = telefone.replace(/^0+/, "");

// Adiciona o código do Brasil
if (!telefone.startsWith("55")) {
  telefone = `55${telefone}`;
}

return {
  json: {
    ...$json,
    telefone,
  },
};

 const textoOriginal = String($json.mensagem || "");

const normalizar = (valor) =>
  String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();

const texto = normalizar(textoOriginal);

const frasesEncerramento = [
  "mensagem automatica",
  "nao precisa responder",
  "atendimento foi finalizado",
  "atendimento finalizado",
  "atendimento encerrado",
  "seu atendimento foi encerrado",
  "protocolo desse atendimento",
  "protocolo de atendimento",
  "finalizado com sucesso",
];

const frasesHorarioAutomatico = [
  "nosso horario de atendimento",
  "horario de atendimento delivery",
  "nosso horario de funcionamento",
  "nosso atendimento e de",
  "horario do nosso atendimento",
  "atendemos de segunda",
  "atendemos de terca",
  "atendemos de quarta",
  "atendemos de quinta",
  "atendemos de sexta",
  "funcionamos de segunda",
  "funcionamos de terca",
  "funcionamos de quarta",
  "funcionamos de quinta",
  "funcionamos de sexta",
  "delivery e de segunda",
  "delivery e de terca",
  "delivery funciona",
];

const termosAtendente = [
  "falar com atendente",
  "fale com atendente",
  "falar com um atendente",
  "falar com uma atendente",
  "atendimento humano",
  "atendente humano",
  "falar com uma pessoa",
  "fale com uma pessoa",
  "falar com consultor",
  "falar com vendedor",
  "falar com especialista",
  "falar com nossa equipe",
];

const termosAlternativos = [
  "outros assuntos",
  "outras opcoes",
  "outras informacoes",
  "suporte",
  "duvidas",
];

const ehEncerramento = frasesEncerramento.some((frase) =>
  texto.includes(frase)
);

const ehHorarioAutomatico = frasesHorarioAutomatico.some((frase) =>
  texto.includes(frase)
);

const possuiHorarioFormatado =
  /\b\d{1,2}(?::\d{2})?\s*(?:h|hs|horas)\b/i.test(texto) ||
  /\bdas\s+\d{1,2}\s+(?:as|a)\s+\d{1,2}/i.test(texto);

const ehMenu =
  texto.includes("digite o numero") ||
  texto.includes("digite uma opcao") ||
  texto.includes("escolha uma opcao") ||
  texto.includes("selecione uma opcao") ||
  texto.includes("informe a opcao") ||
  texto.includes("opcao desejada") ||
  /\[\s*\d{1,2}\s*\]/.test(textoOriginal);

let opcaoAtendente = null;
let confianca = 0;
let termoEncontrado = null;

const linhas = textoOriginal.split(/\r?\n/);

function extrairNumero(linhaOriginal) {
  const padroes = [
    /\[\s*(\d{1,2})\s*\]/,
    /^\s*(\d{1,2})\s*[-–—.)]/,
    /^\s*opcao\s*(\d{1,2})\s*[-–—.:)]?/i,
    /^\s*digite\s*(\d{1,2})\b/i,
  ];

  for (const padrao of padroes) {
    const resultado = linhaOriginal.match(padrao);

    if (resultado) {
      return resultado[1];
    }
  }

  return null;
}

// Procura uma opção diretamente relacionada a um atendente.
for (const linhaOriginal of linhas) {
  const linha = normalizar(linhaOriginal);

  const termo = termosAtendente.find((item) =>
    linha.includes(item)
  );

  if (!termo) {
    continue;
  }

  const numero = extrairNumero(linhaOriginal);

  if (numero) {
    opcaoAtendente = numero;
    confianca = 0.99;
    termoEncontrado = termo;
    break;
  }
}

// Se não encontrou atendente, procura uma opção alternativa.
if (!opcaoAtendente && ehMenu) {
  for (const linhaOriginal of linhas) {
    const linha = normalizar(linhaOriginal);

    const termo = termosAlternativos.find((item) =>
      linha.includes(item)
    );

    if (!termo) {
      continue;
    }

    const numero = extrairNumero(linhaOriginal);

    if (numero) {
      opcaoAtendente = numero;
      confianca = 0.75;
      termoEncontrado = termo;
      break;
    }
  }
}

let classificacao = "HUMANA";
let responderAutomaticamente = false;
let respostaAutomatica = null;

// A ordem é importante: um menu pode possuir uma opção de horário.
if (ehEncerramento) {
  classificacao = "AUTOMATICA_ENCERRAMENTO";
  confianca = 0.99;
  termoEncontrado = termoEncontrado || "encerramento automático";
} else if (opcaoAtendente && confianca >= 0.85) {
  classificacao = "AUTOMATICA_MENU";
  responderAutomaticamente = true;
  respostaAutomatica = opcaoAtendente;
} else if (opcaoAtendente) {
  classificacao = "AUTOMATICA_MENU_REVISAR";
  respostaAutomatica = opcaoAtendente;
} else if (ehMenu) {
  classificacao = "AUTOMATICA_MENU_SEM_ATENDENTE";
  confianca = 0;
} else if (ehHorarioAutomatico && possuiHorarioFormatado) {
  classificacao = "AUTOMATICA_INFORMATIVA";
  confianca = 0.95;
  termoEncontrado = "horário automático";
} else if (ehHorarioAutomatico) {
  classificacao = "AUTOMATICA_INFORMATIVA";
  confianca = 0.85;
  termoEncontrado = "informação de horário";
}

return {
  json: {
    ...$json,
    classificacao,
    mensagem_automatica: classificacao !== "HUMANA",
    responder_automaticamente: responderAutomaticamente,
    resposta_automatica: respostaAutomatica,
    confianca,
    termo_encontrado: termoEncontrado,
  },
};

 if ($json.base64) {
  return { status: "PRECISA_QR", qrCode: $json.base64 };
}

if ($json.instance?.state === "open") {
  return { status: "CONECTADO", qrCode: null };
}

return {
  status: "ERRO_CONEXAO",
  qrCode: null,
  mensagem: $json.message || "Não foi possível conectar"
};

 if ($json.base64) {
  return { status: "PRECISA_QR", qrCode: $json.base64 };
}

if ($json.instance?.state === "open") {
  return { status: "CONECTADO", qrCode: null };
}

return {
  status: "ERRO_CONEXAO",
  qrCode: null,
  mensagem: $json.message || "Não foi possível conectar"
};

 const body = $json.body;

return [{
  json: {
    tipo_evento: "MESSAGES_UPDATE",
    evento_evolution: body.event,
    instancia: body.instance,
    evolution_message_id: body.data?.keyId,
    status_entrega: body.data?.status,
    from_me: body.data?.fromMe
  }
}];
